// Oracle batch 123 (task 0361): the movement-mode hero update (Veldin 0x2062b0, the same code on levels 0, 4, 7, 9, 10 and 13; the Novalis family's build on levels 1, 2, 3, 5) on the levels' own
// data. Run with ORACLE_LEVEL=L build/tests/ovl_oracle --batch 123 (needs the ISO; L = 0, 1, 2, 3, 4, 5, 7, 9, 10, 13). The hero is put in a movement mode (PLAYER+0x20a4 = 1 / 2 / 3)
// in one of the states of the mode, with the stick and the pads varied; the original is the level's own function (ovl_code_lookup), the port is
// hero_move_mode_u (hero_move_mode_tr_1.cpp, generated by tools/codegen/generate_all.py).

#include "ovl_oracle.h"

#include <game/ovl/hero_move_mode.h>
#include <game/ovl/ovl_common.h>
#include <game/ovl/ovl_reloc.h>
#include <runtime/kernel/disc.h>

#include <cstring>
#include <vector>

namespace rac1::oracle {

void batch_123() {
    if (g_only_batch != 123) return;
    g_batch = 123;
    g_ignored_words = vcross_lanes();
    const bool null_ram = g_ee_null_is_ram;
    g_ee_null_is_ram = true;  // as in the runtime
    for (uint32_t a = 0; a < 0x100; a += 4) g_ignored_words.push_back(a);
    for (uint32_t a = 0x70003700; a < 0x70003720; a += 4) g_ignored_words.push_back(a);

    // 989snd's IOP server (as batch 103's): replies a function of the command
    {
        auto result = [](uint32_t id, uint32_t a0) -> uint32_t {
            const uint32_t h = (id * 0x9e3779b1u) ^ (a0 * 0x85ebca6bu);
            return ((h >> 7) % 4 == 0) ? 0u : ((h >> 3) | 1u);
        };
        sif_rpc_register(0x123456, [result](uint32_t fno, uint32_t send, uint32_t, uint32_t recv, uint32_t) {
            if (fno == 0x4d) {
                const uint32_t n = ee_read<uint32_t>(send);
                uint32_t p = send + 4;
                for (uint32_t i = 0; i < n; ++i) {
                    const uint32_t id = ee_read<uint16_t>(p), size = ee_read<uint16_t>(p + 2);
                    ee_write<uint32_t>(recv + 4 + i * 4, result(id, size != 0 ? ee_read<uint32_t>(p + 4) : 0u));
                    if (id == 0x38) {
                        disc_read_ee(ee_read<uint32_t>(p + 0xc), ee_read<uint32_t>(p + 4), ee_read<uint32_t>(p + 8));
                        ee_write<uint32_t>(0x00137b10, 0);
                        ee_write<uint32_t>(0x00137b00, 0);
                    }
                    p += 4 + ((size + 3) & ~3u);
                }
                ee_write<uint32_t>(recv, 0xffffffffu);
                ee_write<uint32_t>(recv + 4 + n * 4, 0xffffffffu);
                return;
            }
            ee_write<uint32_t>(recv + 4, result(fno, send != 0 ? ee_read<uint32_t>(send) : 0u));
            ee_write<uint32_t>(recv, 0xffffffffu);
            ee_write<uint32_t>(recv + 8, 0xffffffffu);
        });
    }
    // the level after its first gameplay frame (the port's), the hero's equipment existing
    static std::vector<uint8_t> snap;
    auto level = [] {
        uint8_t* ram = ee_get_ram_base();
        if (snap.empty()) {
            veldin_boot();
            level_setup_body(1, 0);
            w32(OV(0x0016c060), 0xf);
            gameplay_frame();
            snap.assign(ram, ram + 0x02000000);
        } else {
            std::memcpy(ram, snap.data(), snap.size());
        }
    };
    // Veldin 0x2062b0 (0x958 bytes) is the same code on Veldin, Eudora, Umbris, Gaspar, Orxon and Gemlik Base (the map's `fn 002062b0` line): the Veldin port, the original at the level's equivalent. The
    // Novalis family's build (0x3a8 bytes) is the same words on Novalis, Aridia, Kerwan, Rilgar, Batalia and Pokitaru, transliterated at each level's own address.
    struct Own { int level; uint32_t addr; void (*fn)(); };
    static const Own owns[] = {
        {1, 0x00228000, hero_move_mode_l1},
        {2, 0x00217158, hero_move_mode_l1},
        {3, 0x001ffa88, hero_move_mode_l1},
        {5, 0x00234dd8, hero_move_mode_l1},
    };
    const Own* own = nullptr;
    for (const Own& o : owns) if (o.level == g_oracle_level) own = &o;
    const bool veldin_code = g_oracle_level == 0 || g_oracle_level == 4 || g_oracle_level == 7 || g_oracle_level == 9 || g_oracle_level == 10 || g_oracle_level == 13;
    if (veldin_code || own != nullptr) {
        // the kernel stand-ins and the level change request (unported on both sides)
        g_extra_noop_hooks = {0x00122298, 0x00120478, 0x001232c8, 0x00122fe0, 0x00118a80, OVF(0x0024d430)};
        // 0x17431c: a float of the mobys_in_sphere's output area whose zero's sign depends on a VU0 register left behind (a stale lane of the interpreter's / the port's VU0 state)
        g_ignored_words.push_back(OV(0x0017431c));
        auto gen = [level] {
            level();
            const uint32_t P = 0x0013f350;
            const int mode = ri(1, 3);
            w8(P + 0x20a4, u(mode));
            static const uint32_t st1[] = {0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4a, 0x4b, 0x4c, 0x4d, 0x4e, 0x4f};
            static const uint32_t st2[] = {0x5a, 0x5b, 0x5c, 0x5d, 0x5e, 0x5f, 0x60, 0x61, 0x62};
            static const uint32_t st3[] = {0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x52};
            const uint32_t state = mode == 1 ? st1[ri(0, 12)] : mode == 2 ? st2[ri(0, 8)] : st3[ri(0, 7)];
            w32(P + 0x2090, state);
            if (ri(0, 2) == 0) { Vec4 q = ee_ref<Vec4>(P + 0x80); q.x += rf(-3, 3); q.y += rf(-3, 3); q.z += rf(-2, 2); ee_ref<Vec4>(P + 0x80) = q; }
            if (ri(0, 2) == 0) wfrand(P + 0x90, 3, -2, 2);
            w32(OV(0x0015f5cc), R() & 0xffff);
            seed_rand();
            return Args{};
        };
        if (veldin_code) {
            check("hero_move_mode", 0x002062b0, 300, Ret::None, gen, [](A) { hero_move_mode(); return uint64_t{0}; });
        } else {
            auto fn = own->fn;
            std::printf("%-26s L%d:0x%08x\n", "hero_move_mode", own->level, own->addr);
            if (!check_fn("hero_move_mode", own->addr, 300, Ret::None, gen, [fn](A) { fn(); return uint64_t{0}; }, Scope::FullRam, 0, 0)) ++g_fail;
        }
        g_ignored_words.pop_back();
        g_extra_noop_hooks.clear();
    } else {
        std::printf("%-26s skipped (level %d: Blarg's / Batalia's / Pokitaru's own build, proved in their hero batches / batch 124)\n", "hero_move_mode", g_oracle_level);
        ++g_skipped;
    }

    //@@NEXT
    g_ee_null_is_ram = null_ram;
    g_extra_noop_hooks.clear();
}

}  // namespace rac1::oracle
